"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { useMounted } from "../lib/hooks";
import { formatTime } from "../lib/date";

import {
  type LaidOutEvent,
  type ScheduleEvent,
  type ScheduleResource,
  type ScheduleTone,
  packLanes,
} from "../lib/schedule";

export type { ScheduleEvent, ScheduleResource, ScheduleTone };

/** Oude naam voor ScheduleResource; blijft werken. */
export type ScheduleDay = ScheduleResource;

/** Een event zoals WeekSchedule het accepteert: `resource` of het oudere `day`. */
export type WeekScheduleEvent = Omit<ScheduleEvent, "resource"> & { resource?: string; day?: string };

export interface ScheduleChange {
  /** Sleutel van de kolom waar het blok nu staat. */
  resource: string;
  /** Zelfde waarde als `resource`; blijft bestaan voor bestaande code. */
  day: string;
  start: number;
  end: number;
}

export interface WeekScheduleProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "onChange"> {
  /** Kolommen: dagen, artsen, kamers … Gedeeld met de andere agendaweergaven. */
  resources?: ScheduleResource[];
  /** Oude naam voor `resources`; blijft werken. */
  days?: ScheduleResource[];
  events: WeekScheduleEvent[];
  /** Eerste zichtbare uur. */
  startHour?: number;
  /** Laatste zichtbare uur. */
  endHour?: number;
  /** Hoogte van één uur in pixels. */
  hourHeight?: number;
  /** Rooster waarop verslepen vastklikt, in minuten. */
  step?: number;
  /** Kortste duur bij het verkleinen van een blok. */
  minDuration?: number;
  /** Werkuren per kolomsleutel; daarbuiten wordt gearceerd. */
  workingHours?: Record<string, { start: number; end: number } | null | undefined>;
  /** Lijn met de huidige tijd (alleen op de dag met `today`). */
  nowIndicator?: boolean;
  /** Voor tests: vaste "nu"-tijd in minuten. */
  now?: number;
  /** Blokken kunnen niet versleept of aangepast worden. */
  readOnly?: boolean;
  onEventClick?: (event: ScheduleEvent) => void;
  /** Wordt aangeroepen na slepen of verkleinen. */
  onEventChange?: (id: string, change: ScheduleChange) => void;
  /** Klik op een leeg stuk van een dagkolom. */
  onSlotClick?: (resource: string, start: number) => void;
  /** Eigen inhoud in een blok. */
  renderEvent?: (event: ScheduleEvent) => React.ReactNode;
}

interface DragState {
  id: string;
  mode: "move" | "resize";
  pointerId: number;
  grabOffset: number;
  duration: number;
  draft: ScheduleChange;
}

/**
 * WeekSchedule — weekplanning met uurraster, gepositioneerde blokken,
 * overlappende diensten naast elkaar, en eigen drag & drop (geen dnd-library).
 */
export const WeekSchedule = React.forwardRef<HTMLDivElement, WeekScheduleProps>(function WeekSchedule(
  {
    resources,
    days,
    events,
    startHour = 7,
    endHour = 19,
    hourHeight = 56,
    step = 15,
    minDuration = 15,
    workingHours,
    nowIndicator = true,
    now,
    readOnly,
    onEventClick,
    onEventChange,
    onSlotClick,
    renderEvent,
    className,
    style,
    ...rest
  },
  ref
) {
  // Eén model, twee namen: `resources` is de nieuwe, `days` blijft werken.
  const columnsList = React.useMemo<ScheduleResource[]>(() => resources ?? days ?? [], [resources, days]);
  const items = React.useMemo<ScheduleEvent[]>(
    () => events.map((event) => ({ ...event, resource: event.resource ?? event.day ?? "" })),
    [events]
  );

  const dayStart = startHour * 60;
  const dayEnd = endHour * 60;
  const totalMinutes = Math.max(60, dayEnd - dayStart);
  const bodyRef = React.useRef<HTMLDivElement>(null);
  const [drag, setDrag] = React.useState<DragState | null>(null);
  const [clock, setClock] = React.useState<number>(() => now ?? minutesNow());

  React.useEffect(() => {
    if (now != null || !nowIndicator) return;
    const timer = window.setInterval(() => setClock(minutesNow()), 60_000);
    return () => window.clearInterval(timer);
  }, [now, nowIndicator]);

  // Zonder vaste now-prop kent de server de klok van de bezoeker niet; de
  // lijn verschijnt daarom pas na de eerste render in de browser.
  const gemonteerd = useMounted();
  const toonNu = now != null || gemonteerd;
  const currentMinutes = now ?? clock;
  const hours = Array.from({ length: endHour - startHour + 1 }, (_, index) => startHour + index);

  const toOffset = (minutes: number) => ((minutes - dayStart) / 60) * hourHeight;
  const toMinutes = (offset: number) => dayStart + (offset / hourHeight) * 60;
  const snap = (minutes: number) => Math.round(minutes / step) * step;

  /* ---------------- Slepen ---------------- */
  const columnRects = () => {
    const nodes = bodyRef.current?.querySelectorAll<HTMLElement>("[data-day-key]") ?? [];
    return Array.from(nodes).map((node) => ({
      key: node.dataset.dayKey as string,
      rect: node.getBoundingClientRect(),
    }));
  };

  const beginDrag = (
    event: React.PointerEvent,
    item: ScheduleEvent,
    mode: "move" | "resize"
  ) => {
    if (readOnly || item.locked || item.blocked || !onEventChange) return;
    event.stopPropagation();
    (event.currentTarget as HTMLElement).setPointerCapture(event.pointerId);

    const column = (event.currentTarget as HTMLElement).closest<HTMLElement>("[data-day-key]");
    const top = column?.getBoundingClientRect().top ?? 0;
    const pointerMinutes = toMinutes(event.clientY - top);

    setDrag({
      id: item.id,
      mode,
      pointerId: event.pointerId,
      grabOffset: pointerMinutes - item.start,
      duration: item.end - item.start,
      draft: change(item.resource, item.start, item.end),
    });
  };

  const moveDrag = (event: React.PointerEvent) => {
    if (!drag || event.pointerId !== drag.pointerId) return;
    const columns = columnRects();
    if (columns.length === 0) return;

    const column =
      columns.find((entry) => event.clientX >= entry.rect.left && event.clientX <= entry.rect.right) ??
      columns.find((entry) => entry.key === drag.draft.resource) ??
      columns[0];

    const pointerMinutes = toMinutes(event.clientY - column.rect.top);

    if (drag.mode === "move") {
      let start = snap(pointerMinutes - drag.grabOffset);
      start = Math.min(Math.max(start, dayStart), dayEnd - drag.duration);
      setDrag({ ...drag, draft: change(column.key, start, start + drag.duration) });
      return;
    }

    let end = snap(pointerMinutes);
    end = Math.min(Math.max(end, drag.draft.start + minDuration), dayEnd);
    setDrag({ ...drag, draft: { ...drag.draft, end } });
  };

  const endDrag = (event: React.PointerEvent) => {
    if (!drag || event.pointerId !== drag.pointerId) return;
    const original = items.find((entry) => entry.id === drag.id);
    const changed =
      original &&
      (original.resource !== drag.draft.resource ||
        original.start !== drag.draft.start ||
        original.end !== drag.draft.end);
    if (changed) onEventChange?.(drag.id, drag.draft);
    setDrag(null);
  };

  /* ---------------- Toetsenbord ---------------- */
  const onEventKeyDown = (event: React.KeyboardEvent, item: ScheduleEvent) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      onEventClick?.(item);
      return;
    }
    if (readOnly || item.locked || item.blocked || !onEventChange) return;

    const dayIndex = columnsList.findIndex((column) => column.key === item.resource);
    const duration = item.end - item.start;

    if (event.key === "ArrowUp" || event.key === "ArrowDown") {
      event.preventDefault();
      const direction = event.key === "ArrowUp" ? -1 : 1;
      if (event.shiftKey) {
        const end = Math.min(Math.max(item.end + direction * step, item.start + minDuration), dayEnd);
        onEventChange(item.id, change(item.resource, item.start, end));
        return;
      }
      const start = Math.min(Math.max(item.start + direction * step, dayStart), dayEnd - duration);
      onEventChange(item.id, change(item.resource, start, start + duration));
      return;
    }

    if (event.key === "ArrowLeft" || event.key === "ArrowRight") {
      event.preventDefault();
      const next = dayIndex + (event.key === "ArrowLeft" ? -1 : 1);
      if (next < 0 || next >= columnsList.length) return;
      onEventChange(item.id, change(columnsList[next].key, item.start, item.end));
    }
  };

  /* ---------------- Weergave ---------------- */
  const eventsByColumn = React.useMemo(() => {
    const map = new Map<string, ScheduleEvent[]>();
    for (const column of columnsList) map.set(column.key, []);
    for (const item of items) {
      const draft = drag?.id === item.id ? { ...item, ...drag.draft } : item;
      const list = map.get(draft.resource);
      if (list) list.push(draft);
    }
    return map;
  }, [columnsList, items, drag]);

  return (
    <div
      ref={ref}
      className={cn("lui-schedule", drag && "lui-schedule-dragging", className)}
      style={
        {
          ...style,
          ["--lui-hour-height" as string]: `${hourHeight}px`,
          ["--lui-schedule-columns" as string]: String(columnsList.length),
        } as React.CSSProperties
      }
      {...rest}
    >
      <div className="lui-schedule-scroll">
        <div className="lui-schedule-inner">
          {/* Kop met dagen */}
          <div className="lui-schedule-head">
            <div className="lui-schedule-gutter-head" />
            {columnsList.map((day) => (
              <div
                key={day.key}
                className="lui-schedule-dayhead"
                data-today={day.today ? "" : undefined}
              >
                <span className="lui-schedule-dayname">{day.label}</span>
                {day.sublabel && <span className="lui-schedule-daysub">{day.sublabel}</span>}
              </div>
            ))}
          </div>

          {/* Raster */}
          <div
            className="lui-schedule-body"
            ref={bodyRef}
            style={{ height: (totalMinutes / 60) * hourHeight }}
            onPointerMove={moveDrag}
            onPointerUp={endDrag}
            onPointerCancel={endDrag}
          >
            <div className="lui-schedule-gutter">
              {hours.map((hour) => (
                <span
                  key={hour}
                  className="lui-schedule-hour"
                  style={{ top: toOffset(hour * 60) }}
                >
                  {formatTime(hour * 60)}
                </span>
              ))}
            </div>

            {columnsList.map((day) => {
              const work = workingHours?.[day.key];
              const laid = packLanes(eventsByColumn.get(day.key) ?? []);

              return (
                <div key={day.key} className="lui-schedule-column" data-day-key={day.key}>
                  {/* Uurlijnen */}
                  <div className="lui-schedule-lines" aria-hidden="true" />

                  {/* Buiten de werkuren */}
                  {day.blocked ? (
                    <div className="lui-schedule-hatch lui-schedule-hatch-full">
                      {day.blockedLabel && (
                        <span className="lui-schedule-hatch-label">{day.blockedLabel}</span>
                      )}
                    </div>
                  ) : (
                    work && (
                      <>
                        {work.start > dayStart && (
                          <div
                            className="lui-schedule-hatch"
                            style={{ top: 0, height: toOffset(work.start) }}
                          />
                        )}
                        {work.end < dayEnd && (
                          <div
                            className="lui-schedule-hatch"
                            style={{ top: toOffset(work.end), bottom: 0 }}
                          />
                        )}
                      </>
                    )
                  )}

                  {/* Klikvlak voor nieuwe blokken */}
                  {onSlotClick && !readOnly && !day.blocked && (
                    <button
                      type="button"
                      className="lui-schedule-slots"
                      aria-label={`Nieuw blok op ${day.label}`}
                      onClick={(event) => {
                        const rect = event.currentTarget.getBoundingClientRect();
                        onSlotClick(day.key, snap(toMinutes(event.clientY - rect.top)));
                      }}
                    />
                  )}

                  {/* Nu-lijn */}
                  {nowIndicator && toonNu && day.today && currentMinutes >= dayStart && currentMinutes <= dayEnd && (
                    <div className="lui-schedule-now" style={{ top: toOffset(currentMinutes) }}>
                      <span className="lui-schedule-now-dot" />
                    </div>
                  )}

                  {/* Blokken */}
                  {laid.map(({ event: item, lane, lanes }: LaidOutEvent<ScheduleEvent>) => {
                    const top = toOffset(Math.max(item.start, dayStart));
                    const height = Math.max(
                      18,
                      toOffset(Math.min(item.end, dayEnd)) - toOffset(Math.max(item.start, dayStart))
                    );
                    const width = 100 / lanes;
                    const isDragging = drag?.id === item.id;
                    const tone = item.tone ?? "accent";
                    const isBlocked = Boolean(item.blocked);

                    return (
                      <div
                        key={item.id}
                        role="button"
                        tabIndex={0}
                        data-dragging={isDragging ? "" : undefined}
                        data-locked={item.locked || isBlocked ? "" : undefined}
                        data-blocked={isBlocked ? "" : undefined}
                        className={cn(
                          "lui-schedule-event",
                          isBlocked ? "lui-schedule-event-blocked" : `lui-schedule-event-${tone}`
                        )}
                        style={{
                          top,
                          height,
                          left: `calc(${lane * width}% + 2px)`,
                          width: `calc(${width}% - 4px)`,
                          ...(item.color
                            ? ({ ["--lui-event-color" as string]: item.color } as React.CSSProperties)
                            : {}),
                        }}
                        onPointerDown={(event) => !isBlocked && beginDrag(event, item, "move")}
                        onClick={() => !drag && !isBlocked && onEventClick?.(item)}
                        onKeyDown={(event) => onEventKeyDown(event, item)}
                        aria-label={`${item.title}, ${formatTime(item.start)} tot ${formatTime(item.end)}`}
                      >
                        {renderEvent ? (
                          renderEvent(item)
                        ) : (
                          <>
                            <span className="lui-schedule-event-time">
                              {formatTime(item.start)} – {formatTime(item.end)}
                            </span>
                            <span className="lui-schedule-event-title">{item.title}</span>
                            {item.subtitle && height > 54 && (
                              <span className="lui-schedule-event-sub">{item.subtitle}</span>
                            )}
                          </>
                        )}

                        {!readOnly && !item.locked && !isBlocked && onEventChange && (
                          <span
                            className="lui-schedule-handle"
                            aria-hidden="true"
                            onPointerDown={(event) => beginDrag(event, item, "resize")}
                          />
                        )}
                      </div>
                    );
                  })}
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
});

function change(resource: string, start: number, end: number): ScheduleChange {
  return { resource, day: resource, start, end };
}

function minutesNow(): number {
  const date = new Date();
  return date.getHours() * 60 + date.getMinutes();
}

/* ============================ WeekSchedule ============================ */
.lui-schedule {
  --lui-hour-height: 56px;
  --lui-gutter: 58px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--r-lg);
  box-shadow: var(--sh-sm);
  overflow: hidden;
}
.lui-schedule-scroll { overflow: auto; -webkit-overflow-scrolling: touch; max-height: 100%; }
.lui-schedule-inner { min-width: 680px; }

/* ---------- Kop ---------- */
.lui-schedule-head {
  display: grid;
  grid-template-columns: var(--lui-gutter) repeat(var(--lui-schedule-columns), minmax(0, 1fr));
  position: sticky; top: 0; z-index: 3;
  background: var(--surface-2);
  border-bottom: 1px solid var(--border);
}
.lui-schedule-gutter-head { border-right: 1px solid var(--border); }
.lui-schedule-dayhead {
  display: flex; flex-direction: column; align-items: center; gap: 1px;
  padding: 9px 6px; border-right: 1px solid var(--border);
}
.lui-schedule-dayhead:last-child { border-right: none; }
.lui-schedule-dayname {
  font-size: 11px; font-weight: 650; letter-spacing: .05em;
  text-transform: uppercase; color: var(--text-3);
}
.lui-schedule-daysub {
  font-size: 16px; font-weight: 700; letter-spacing: -0.02em; color: var(--text);
  font-variant-numeric: tabular-nums;
}
.lui-schedule-dayhead[data-today] .lui-schedule-dayname { color: var(--accent); }
.lui-schedule-dayhead[data-today] .lui-schedule-daysub {
  color: var(--accent-fg); background: var(--accent);
  border-radius: var(--r-full); min-width: 26px; text-align: center; padding: 0 6px;
}

/* ---------- Raster ---------- */
.lui-schedule-body {
  position: relative; display: grid;
  grid-template-columns: var(--lui-gutter) repeat(var(--lui-schedule-columns), minmax(0, 1fr));
}

.lui-schedule-gutter {
  position: relative; border-right: 1px solid var(--border); background: var(--surface);
}
.lui-schedule-hour {
  position: absolute; right: 8px; transform: translateY(-50%);
  font-size: 11px; font-weight: 600; color: var(--text-3);
  font-variant-numeric: tabular-nums; white-space: nowrap;
}
/* Het eerste en laatste uurlabel blijven binnen het raster staan. */
.lui-schedule-hour:first-child { transform: translateY(0); }
.lui-schedule-hour:last-child { transform: translateY(-100%); }

.lui-schedule-column {
  position: relative; border-right: 1px solid var(--border); min-width: 0;
}
.lui-schedule-column:last-child { border-right: none; }

.lui-schedule-lines {
  position: absolute; inset: 0; pointer-events: none;
  background-image: repeating-linear-gradient(
    to bottom,
    var(--border) 0,
    var(--border) 1px,
    transparent 1px,
    transparent var(--lui-hour-height)
  );
}

.lui-schedule-hatch {
  position: absolute; left: 0; right: 0; pointer-events: none;
  background-image: repeating-linear-gradient(
    45deg,
    var(--surface-2) 0,
    var(--surface-2) 5px,
    var(--surface-3) 5px,
    var(--surface-3) 10px
  );
  opacity: .85;
}
.lui-schedule-hatch-full {
  top: 0; bottom: 0; display: grid; place-items: center;
}
.lui-schedule-hatch-label {
  font-size: 11px; font-weight: 650; color: var(--text-3);
  background: var(--surface); border: 1px solid var(--border);
  border-radius: var(--r-full); padding: 3px 10px;
  text-transform: uppercase; letter-spacing: .05em;
}

.lui-schedule-slots {
  position: absolute; inset: 0; width: 100%; height: 100%;
  border: none; background: transparent; cursor: copy; padding: 0;
}
.lui-schedule-slots:hover { background: color-mix(in srgb, var(--accent) 5%, transparent); }
.lui-schedule-slots:focus-visible { outline: none; box-shadow: inset var(--ring); }

/* ---------- Nu-lijn ---------- */
.lui-schedule-now {
  position: absolute; left: 0; right: 0; height: 2px;
  background: var(--red); z-index: 2; pointer-events: none;
}
.lui-schedule-now-dot {
  position: absolute; left: -3px; top: -3px;
  width: 8px; height: 8px; border-radius: var(--r-full); background: var(--red);
}

/* ---------- Blokken ---------- */
.lui-schedule-event {
  --lui-event-color: var(--accent);
  position: absolute; z-index: 1;
  display: flex; flex-direction: column; gap: 1px;
  padding: 5px 8px; overflow: hidden;
  border-radius: var(--r-xs);
  border: 1px solid color-mix(in srgb, var(--lui-event-color) 35%, transparent);
  border-left: 3px solid var(--lui-event-color);
  background: color-mix(in srgb, var(--lui-event-color) 13%, var(--surface));
  color: var(--text);
  cursor: grab; touch-action: none; user-select: none;
  transition: box-shadow var(--dur-fast), transform var(--dur-fast);
}
.lui-schedule-event:hover { box-shadow: var(--sh-md); z-index: 2; }
.lui-schedule-event:focus-visible { outline: none; box-shadow: var(--ring); z-index: 3; }
.lui-schedule-event[data-locked] { cursor: default; }
.lui-schedule-event[data-dragging] {
  cursor: grabbing; z-index: 4; box-shadow: var(--sh-lg);
  transform: scale(1.015); opacity: .95;
}
.lui-schedule-dragging { cursor: grabbing; }
.lui-schedule-dragging .lui-schedule-slots { pointer-events: none; }

.lui-schedule-event-time {
  font-size: 10.5px; font-weight: 650; color: var(--lui-event-color);
  font-variant-numeric: tabular-nums; white-space: nowrap;
}
.lui-schedule-event-title {
  font-size: 12px; font-weight: 650; color: var(--text);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.lui-schedule-event-sub {
  font-size: 11px; color: var(--text-2);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}

.lui-schedule-event-accent { --lui-event-color: var(--accent); }
.lui-schedule-event-green { --lui-event-color: var(--green); }
.lui-schedule-event-amber { --lui-event-color: var(--amber); }
.lui-schedule-event-red { --lui-event-color: var(--red); }
.lui-schedule-event-blue { --lui-event-color: var(--blue); }
.lui-schedule-event-violet { --lui-event-color: var(--violet); }
.lui-schedule-event-neutral { --lui-event-color: var(--text-3); }

.lui-schedule-handle {
  position: absolute; left: 0; right: 0; bottom: 0; height: 8px;
  cursor: ns-resize; touch-action: none;
}
.lui-schedule-handle::after {
  content: ""; position: absolute; left: 50%; bottom: 2px;
  transform: translateX(-50%);
  width: 22px; height: 2px; border-radius: var(--r-full);
  background: color-mix(in srgb, var(--lui-event-color) 55%, transparent);
  opacity: 0; transition: opacity var(--dur-fast);
}
.lui-schedule-event:hover .lui-schedule-handle::after { opacity: 1; }

@media (max-width: 720px) {
  .lui-schedule { --lui-gutter: 46px; }
  .lui-schedule-daysub { font-size: 14px; }
}

/* ---------- Geblokkeerd blok ---------- */
.lui-schedule-event-blocked {
  --lui-event-color: var(--red);
  cursor: default;
  border-color: color-mix(in srgb, var(--red) 30%, transparent);
  border-left-color: color-mix(in srgb, var(--red) 55%, transparent);
  background-image: repeating-linear-gradient(
    -45deg,
    var(--red-tint) 0,
    var(--red-tint) 4px,
    var(--surface) 4px,
    var(--surface) 9px
  );
  color: var(--red);
}
.lui-schedule-event-blocked .lui-schedule-event-title { color: var(--red); }
.lui-schedule-event-blocked:hover { box-shadow: none; }

/**
 * Datumhulpfuncties — eigen implementatie op basis van de ingebouwde Date en
 * Intl. Geen date-fns, geen dayjs, geen luxon.
 *
 * Alle functies werken met lokale tijd en laten de meegegeven Date ongemoeid.
 */

export interface DateRange {
  from?: Date;
  to?: Date;
}

/** Standaardtaal van het Dafke UI-design. */
export const DEFAULT_LOCALE = "nl-BE";

/* ------------------------------------------------------------------ */
/* Basis                                                               */
/* ------------------------------------------------------------------ */

export function startOfDay(date: Date): Date {
  const copy = new Date(date);
  copy.setHours(0, 0, 0, 0);
  return copy;
}

export function addDays(date: Date, amount: number): Date {
  const copy = new Date(date);
  copy.setDate(copy.getDate() + amount);
  return copy;
}

export function addMonths(date: Date, amount: number): Date {
  const copy = new Date(date);
  const day = copy.getDate();
  copy.setDate(1);
  copy.setMonth(copy.getMonth() + amount);
  copy.setDate(Math.min(day, daysInMonth(copy)));
  return copy;
}

export function daysInMonth(date: Date): number {
  return new Date(date.getFullYear(), date.getMonth() + 1, 0).getDate();
}

export function startOfMonth(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth(), 1);
}

export function endOfMonth(date: Date): Date {
  return new Date(date.getFullYear(), date.getMonth() + 1, 0, 23, 59, 59, 999);
}

/** weekStartsOn: 0 = zondag, 1 = maandag (standaard in België). */
export function startOfWeek(date: Date, weekStartsOn = 1): Date {
  const copy = startOfDay(date);
  const diff = (copy.getDay() - weekStartsOn + 7) % 7;
  return addDays(copy, -diff);
}

export function endOfWeek(date: Date, weekStartsOn = 1): Date {
  return addDays(startOfWeek(date, weekStartsOn), 6);
}

/* ------------------------------------------------------------------ */
/* Vergelijken                                                         */
/* ------------------------------------------------------------------ */

export function isSameDay(a?: Date | null, b?: Date | null): boolean {
  if (!a || !b) return false;
  return (
    a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate()
  );
}

export function isSameMonth(a?: Date | null, b?: Date | null): boolean {
  if (!a || !b) return false;
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth();
}

export function isToday(date: Date): boolean {
  return isSameDay(date, new Date());
}

export function isWeekend(date: Date): boolean {
  const day = date.getDay();
  return day === 0 || day === 6;
}

export function isBeforeDay(a: Date, b: Date): boolean {
  return startOfDay(a).getTime() < startOfDay(b).getTime();
}

export function isAfterDay(a: Date, b: Date): boolean {
  return startOfDay(a).getTime() > startOfDay(b).getTime();
}

export function isWithin(date: Date, from?: Date | null, to?: Date | null): boolean {
  if (!from || !to) return false;
  const time = startOfDay(date).getTime();
  const start = startOfDay(from).getTime();
  const end = startOfDay(to).getTime();
  return time >= Math.min(start, end) && time <= Math.max(start, end);
}

export function clampDate(date: Date, min?: Date | null, max?: Date | null): Date {
  if (min && isBeforeDay(date, min)) return new Date(min);
  if (max && isAfterDay(date, max)) return new Date(max);
  return date;
}

/** Aantal hele dagen tussen twee datums (b - a). */
export function differenceInDays(a: Date, b: Date): number {
  const millis = startOfDay(b).getTime() - startOfDay(a).getTime();
  return Math.round(millis / 86_400_000);
}

/* ------------------------------------------------------------------ */
/* Weeknummer (ISO 8601)                                               */
/* ------------------------------------------------------------------ */

export function getISOWeek(date: Date): number {
  const target = startOfDay(date);
  // Donderdag van deze week bepaalt het jaar.
  target.setDate(target.getDate() + 3 - ((target.getDay() + 6) % 7));
  const firstThursday = new Date(target.getFullYear(), 0, 4);
  firstThursday.setDate(firstThursday.getDate() + 3 - ((firstThursday.getDay() + 6) % 7));
  return 1 + Math.round((target.getTime() - firstThursday.getTime()) / (7 * 86_400_000));
}

/* ------------------------------------------------------------------ */
/* Rasters                                                             */
/* ------------------------------------------------------------------ */

/** Alle dagen van de maand, aangevuld tot volledige weken (6 × 7 = 42 dagen). */
export function getMonthGrid(month: Date, weekStartsOn = 1): Date[] {
  const first = startOfWeek(startOfMonth(month), weekStartsOn);
  return Array.from({ length: 42 }, (_, index) => addDays(first, index));
}

/** De zeven (of minder) dagen van een week vanaf een datum. */
export function getWeekDays(date: Date, weekStartsOn = 1, length = 7): Date[] {
  const first = startOfWeek(date, weekStartsOn);
  return Array.from({ length }, (_, index) => addDays(first, index));
}

/* ------------------------------------------------------------------ */
/* Formatteren                                                         */
/* ------------------------------------------------------------------ */

const formatterCache = new Map<string, Intl.DateTimeFormat>();

function formatter(locale: string, options: Intl.DateTimeFormatOptions): Intl.DateTimeFormat {
  const key = `${locale}|${JSON.stringify(options)}`;
  let cached = formatterCache.get(key);
  if (!cached) {
    cached = new Intl.DateTimeFormat(locale, options);
    formatterCache.set(key, cached);
  }
  return cached;
}

export function formatDate(
  date: Date,
  options: Intl.DateTimeFormatOptions = { day: "2-digit", month: "short", year: "numeric" },
  locale: string = DEFAULT_LOCALE
): string {
  return formatter(locale, options).format(date);
}

/** "16 – 20 mrt 2026" of "28 feb – 3 mrt 2026" bij een maandgrens. */
export function formatDateRange(range: DateRange, locale: string = DEFAULT_LOCALE): string {
  if (!range.from) return "";
  if (!range.to || isSameDay(range.from, range.to)) return formatDate(range.from, undefined, locale);

  const sameMonth = isSameMonth(range.from, range.to);
  const sameYear = range.from.getFullYear() === range.to.getFullYear();

  const left = formatDate(
    range.from,
    sameMonth
      ? { day: "numeric" }
      : sameYear
        ? { day: "numeric", month: "short" }
        : { day: "numeric", month: "short", year: "numeric" },
    locale
  );
  const right = formatDate(range.to, { day: "numeric", month: "short", year: "numeric" }, locale);
  return `${left} – ${right}`;
}

/** Namen van de weekdagen, beginnend bij weekStartsOn. */
export function weekdayNames(
  weekStartsOn = 1,
  format: "narrow" | "short" | "long" = "short",
  locale: string = DEFAULT_LOCALE
): string[] {
  const base = new Date(2024, 0, 7); // een zondag
  return Array.from({ length: 7 }, (_, index) =>
    formatter(locale, { weekday: format }).format(addDays(base, (index + weekStartsOn) % 7))
  );
}

export function monthName(month: Date, locale: string = DEFAULT_LOCALE): string {
  return formatDate(month, { month: "long", year: "numeric" }, locale);
}

/* ------------------------------------------------------------------ */
/* Tijd (minuten sinds middernacht)                                     */
/* ------------------------------------------------------------------ */

/** "9:30", "930", "9.30" of "0930" → 570. Geeft null bij onleesbare invoer. */
export function parseTime(input: string): number | null {
  const clean = input.trim().replace(/[.,]/g, ":");
  if (!clean) return null;

  const withSeparator = clean.match(/^(\d{1,2}):(\d{1,2})$/);
  if (withSeparator) {
    return toMinutes(Number(withSeparator[1]), Number(withSeparator[2]));
  }

  const digits = clean.replace(/\D/g, "");
  if (!digits) return null;
  if (digits.length <= 2) return toMinutes(Number(digits), 0);
  if (digits.length === 3) return toMinutes(Number(digits.slice(0, 1)), Number(digits.slice(1)));
  return toMinutes(Number(digits.slice(0, 2)), Number(digits.slice(2, 4)));
}

function toMinutes(hours: number, minutes: number): number | null {
  if (!Number.isFinite(hours) || !Number.isFinite(minutes)) return null;
  if (hours > 23 || minutes > 59) return null;
  return hours * 60 + minutes;
}

/** 570 → "09:30". */
export function formatTime(minutes: number): string {
  const total = ((Math.round(minutes) % 1440) + 1440) % 1440;
  const hours = Math.floor(total / 60);
  const rest = total % 60;
  return `${String(hours).padStart(2, "0")}:${String(rest).padStart(2, "0")}`;
}

/** Rondt af op een veelvoud van `step` minuten. */
export function roundToStep(minutes: number, step: number): number {
  if (step <= 0) return minutes;
  return Math.round(minutes / step) * step;
}

/** Alle tijdstippen tussen from en to, met stappen van `step` minuten. */
export function timeSlots(from: number, to: number, step: number): number[] {
  const slots: number[] = [];
  for (let minutes = from; minutes <= to; minutes += step) slots.push(minutes);
  return slots;
}

/** "2 u 30" — leesbare duur voor diensten en verlof. */
export function formatDuration(minutes: number): string {
  const hours = Math.floor(minutes / 60);
  const rest = Math.round(minutes % 60);
  if (hours === 0) return `${rest} min`;
  if (rest === 0) return `${hours} u`;
  return `${hours} u ${rest}`;
}

import type * as React from "react";

/**
 * Gedeeld datamodel voor alle agendaweergaven.
 *
 * WeekSchedule, ResourceColumns, Swimlanes en TimeSlotList werken op precies
 * dezelfde gegevens, zodat je met één knop van weergave kunt wisselen zonder
 * je data om te bouwen.
 */

export type ScheduleTone = "accent" | "green" | "amber" | "red" | "blue" | "violet" | "neutral";

/** Een kolom of rij in de agenda: een dag, een arts, een kamer, een machine. */
export interface ScheduleResource {
  /** Unieke sleutel; events verwijzen hiernaar. */
  key: string;
  label: React.ReactNode;
  /** Tweede regel, bv. het dagnummer of het aantal afspraken. */
  sublabel?: React.ReactNode;
  /** Avatar of icoon links van het label. */
  media?: React.ReactNode;
  /** Eigen kleur voor deze resource (koptekst, tag, blokken zonder eigen kleur). */
  color?: string;
  /** Markeert deze kolom als vandaag. */
  today?: boolean;
  /** Hele kolom gearceerd, bv. een sluitingsdag of afwezigheid. */
  blocked?: boolean;
  blockedLabel?: React.ReactNode;
}

export interface ScheduleEvent {
  id: string;
  /** Sleutel van de resource (dag, arts, kamer …) waar dit item bij hoort. */
  resource: string;
  /** Begin in minuten sinds middernacht (09:30 = 570). */
  start: number;
  /** Einde in minuten sinds middernacht. */
  end: number;
  title: React.ReactNode;
  subtitle?: React.ReactNode;
  tone?: ScheduleTone;
  /** Eigen kleur; overschrijft `tone` en de kleur van de resource. */
  color?: string;
  /** Kan niet versleept of aangepast worden. */
  locked?: boolean;
  /** Geblokkeerde tijd: gearceerd, nooit versleepbaar, geen klikactie. */
  blocked?: boolean;
  /** Vrij veld voor je eigen gegevens. */
  meta?: unknown;
}

/** Positie van een event wanneer overlappende items naast elkaar staan. */
export interface LaidOutEvent<T extends { start: number; end: number }> {
  event: T;
  /** Kolomindex binnen de groep overlappende items. */
  lane: number;
  /** Aantal kolommen in die groep. */
  lanes: number;
}

/**
 * Legt overlappende items naast elkaar: items die elkaar raken vormen een
 * cluster en krijgen daarbinnen elk een eigen kolom.
 */
export function packLanes<T extends { start: number; end: number }>(items: T[]): Array<LaidOutEvent<T>> {
  const sorted = [...items].sort((a, b) => a.start - b.start || a.end - b.end);
  const result: Array<LaidOutEvent<T>> = [];

  let cluster: T[] = [];
  let clusterEnd = -1;

  const flush = () => {
    if (cluster.length === 0) return;
    const laneEnds: number[] = [];
    const placed = cluster.map((event) => {
      let lane = laneEnds.findIndex((end) => end <= event.start);
      if (lane === -1) {
        lane = laneEnds.length;
        laneEnds.push(event.end);
      } else {
        laneEnds[lane] = event.end;
      }
      return { event, lane };
    });
    for (const entry of placed) result.push({ ...entry, lanes: laneEnds.length });
    cluster = [];
    clusterEnd = -1;
  };

  for (const event of sorted) {
    if (cluster.length > 0 && event.start >= clusterEnd) flush();
    cluster.push(event);
    clusterEnd = Math.max(clusterEnd, event.end);
  }
  flush();

  return result;
}

/** Groepeert events per resource, in de volgorde van de resources zelf. */
export function groupByResource<T extends { resource: string }>(
  events: T[],
  resources: Array<{ key: string }>
): Map<string, T[]> {
  const map = new Map<string, T[]>();
  for (const resource of resources) map.set(resource.key, []);
  for (const event of events) {
    const list = map.get(event.resource);
    if (list) list.push(event);
  }
  for (const list of map.values()) {
    list.sort((a, b) => ((a as { start?: number }).start ?? 0) - ((b as { start?: number }).start ?? 0));
  }
  return map;
}

/** Groepeert events per starttijd, oplopend — de basis voor een tijdlijn. */
export function groupByStart<T extends { start: number }>(events: T[]): Array<{ start: number; events: T[] }> {
  const map = new Map<number, T[]>();
  for (const event of events) {
    const list = map.get(event.start) ?? [];
    list.push(event);
    map.set(event.start, list);
  }
  return [...map.entries()]
    .sort((a, b) => a[0] - b[0])
    .map(([start, list]) => ({ start, events: list }));
}

/** Telt de items die echt een afspraak zijn (geblokkeerde tijd niet meegerekend). */
export function countBookable(events: Array<{ blocked?: boolean }>): number {
  return events.filter((event) => !event.blocked).length;
}

/** De kleur van een event: eigen kleur, anders die van de resource, anders de toon. */
export function eventColor(
  event: { color?: string; tone?: ScheduleTone },
  resource?: { color?: string }
): string | undefined {
  return event.color ?? resource?.color;
}

/** Huidige tijd in minuten sinds middernacht. */
export function nowMinutes(): number {
  const date = new Date();
  return date.getHours() * 60 + date.getMinutes();
}
